import {expect,test} from 'bun:test';
import {Box3,Matrix4,Quaternion,Vector3} from 'three';
import {validateGaussianManifest,validateGaussianProfile} from '../../src/assets/gaussian-profile.ts';
import {gaussianFixture} from '../helpers/gaussian.ts';

test('distributed fixture bounds contain decoded PLY Gaussian footprints, including every head splat',()=>{
  // Decode the generated bytes independently of the bounds formula. Spark
  // 2.4.0 clips at sqrt(8) sigma; rotating/scaling an ellipsoid gives each
  // coordinate radius from the corresponding matrix row's Euclidean norm.
  for(const index of Array.from({length:8},(_,i)=>i)){
    const fixture=gaussianFixture(index),manifest=validateGaussianManifest(fixture.manifest);
    validateGaussianProfile({kind:'gaussian',userId:'1',assetId:'a'.repeat(64),manifest,scale:1,offsetX:0,offsetY:0,offsetZ:0,yawRad:0});
    const bytes=Buffer.from(fixture.files.find(file=>file.path===manifest.splat)!.bytes),marker=Buffer.from('end_header\n');
    const start=bytes.indexOf(marker)+marker.length,header=bytes.subarray(0,start).toString('utf8');
    const properties=[...header.matchAll(/^property float (\w+)$/gm)].map(match=>match[1]!),count=Number(header.match(/^element vertex (\d+)$/m)![1]);
    expect(count).toBe(fixture.splatCount);
    const body=new Box3(),face=new Box3(),rotationScale=new Matrix4(),center=new Vector3(),quaternion=new Quaternion(),scale=new Vector3(),radius=new Vector3();
    for(let vertex=0;vertex<count;vertex++){
      const read=(name:string)=>{const field=properties.indexOf(name);if(field<0)throw new Error(`Missing PLY field ${name}`);return bytes.readFloatLE(start+(vertex*properties.length+field)*4);};
      center.set(read('x'),read('y'),read('z'));
      scale.set(Math.exp(read('scale_0')),Math.exp(read('scale_1')),Math.exp(read('scale_2')));
      quaternion.set(read('rot_1'),read('rot_2'),read('rot_3'),read('rot_0')).normalize();
      const e=rotationScale.compose(new Vector3(),quaternion,scale).elements;
      radius.set(Math.hypot(e[0]!,e[4]!,e[8]!),Math.hypot(e[1]!,e[5]!,e[9]!),Math.hypot(e[2]!,e[6]!,e[10]!)).multiplyScalar(Math.sqrt(8));
      const low=center.clone().sub(radius),high=center.clone().add(radius);
      body.expandByPoint(low).expandByPoint(high);
      // The fixture's head is the first splat of each four-splat group.
      if(vertex%4===0)face.expandByPoint(low).expandByPoint(high);
    }
    for(const [name,actual] of [['faceBounds',face],['bodyBounds',body],['framingBounds',body]] as const){
      const declared=manifest[name],box=new Box3(new Vector3().fromArray(declared.min),new Vector3().fromArray(declared.max));
      expect(box.containsBox(actual),`character ${index+1} ${name} excludes the rendered Gaussian footprint`).toBe(true);
    }
  }
});
